// ── FF-9: Import-driven source resolution ─────────────────────────────
//
// The compiler takes a flat List<SourceFile>. This layer resolves imports
// transitively: scan source roots to build a module index, then starting
// from entry modules, discover imports and load only what's needed.
// Each module is loaded exactly once (HashMap memoization).
//
// This is the same mechanism as the test harness (helpers.rs) but in the
// production binary. No manual file lists. No guessing which std files
// to include. The compiler follows imports.

/// Recursively find all .dag files under a directory.
fn collect_dag_files(dir: &std::path::Path, files: &mut Vec<std::path::PathBuf>) {
    let mut entries: Vec<_> = std::fs::read_dir(dir)
        .unwrap_or_else(|e| panic!("failed to read dir {:?}: {}", dir, e))
        .filter_map(|e| e.ok())
        .collect();
    entries.sort_by_key(|e| e.file_name());
    for entry in entries {
        let path = entry.path();
        if path.is_dir() {
            collect_dag_files(&path, files);
        } else if path.extension().map(|e| e == "dag").unwrap_or(false) {
            files.push(path);
        }
    }
}

/// Extract the `module x.y.z` declaration from a .dag file's first lines.
/// Uses simple text scanning (not the full parser) to avoid bootstrapping
/// the entire compiler just to read module names.
fn extract_module_path(content: &str) -> Option<String> {
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.starts_with("module ") {
            return Some(trimmed["module ".len()..].trim().to_string());
        }
        // Skip comments and blank lines at the top
        if !trimmed.is_empty() && !trimmed.starts_with("//") {
            break;
        }
    }
    None
}

/// Extract import module paths from a .dag file's import declarations.
/// Simple text scanning — reads `import x.y.z { ... }` lines.
fn extract_import_paths(content: &str) -> Vec<String> {
    let mut imports = Vec::new();
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.starts_with("import ") {
            // import x.y.z { ... } or import x.y.z
            let rest = trimmed["import ".len()..].trim();
            let module_path = rest.split('{').next().unwrap_or(rest).trim();
            if !module_path.is_empty() {
                imports.push(module_path.to_string());
            }
        }
    }
    imports
}

/// Build module index: scan all source roots, map module_path → file_path.
fn build_module_index(source_roots: &[String]) -> HashMap<String, std::path::PathBuf> {
    let mut index = HashMap::new();
    for root in source_roots {
        let root_path = std::path::Path::new(root);
        if !root_path.exists() {
            continue;
        }
        let mut dag_files = Vec::new();
        collect_dag_files(root_path, &mut dag_files);
        for path in dag_files {
            if let Ok(content) = std::fs::read_to_string(&path) {
                if let Some(module_path) = extract_module_path(&content) {
                    index.insert(module_path, path);
                }
            }
        }
    }
    index
}

/// Resolve imports transitively from entry modules. Returns the minimal
/// set of SourceFiles needed — each module loaded exactly once.
fn resolve_transitively_with_seen(
    entry_sources: Vec<(String, String)>,  // (path, content)
    index: &HashMap<String, std::path::PathBuf>,
    mut seen: HashMap<String, Rc<v2_compiler_compile::SourceFile>>,
) -> Vec<Rc<v2_compiler_compile::SourceFile>> {
    let mut queue: Vec<(String, String)> = entry_sources;

    if !seen.contains_key("std.types") {
        if let Some(file_path) = index.get("std.types") {
            if let Ok(file_content) = std::fs::read_to_string(file_path) {
                let rel_path = file_path.to_string_lossy().to_string();
                let source = Rc::new(v2_compiler_compile::SourceFile {
                    path: rel_path.clone(),
                    content: file_content.clone(),
                });
                seen.insert("std.types".to_string(), source);
                queue.push((rel_path, file_content));
            }
        }
    }

    while let Some((_path, content)) = queue.pop() {
        let imports = extract_import_paths(&content);
        for module_path in imports {
            if seen.contains_key(&module_path) {
                continue;
            }
            if let Some(file_path) = index.get(&module_path) {
                if let Ok(file_content) = std::fs::read_to_string(file_path) {
                    let rel_path = file_path.to_string_lossy().to_string();
                    let source = Rc::new(v2_compiler_compile::SourceFile {
                        path: rel_path.clone(),
                        content: file_content.clone(),
                    });
                    seen.insert(module_path, source);
                    queue.push((rel_path, file_content));
                }
            }
            // If not found, compiler's resolve stage will report the error.
        }
    }

    seen.into_values().collect()
}

fn main() {
    let cli = Cli::parse();
    let _result = match cli.command {
        Commands::Compile { source_roots, source_dir, output_dir, target } => {
            let render_target = match target.as_str() {
                "rust" => v2_compiler_artifact::RenderTarget::Rust,
                "python" => v2_compiler_artifact::RenderTarget::Python,
                "go" => v2_compiler_artifact::RenderTarget::Go,
                "dag" => v2_compiler_artifact::RenderTarget::Dag,
                other => {
                    eprintln!("unknown target: {}. supported: rust, python, go, dag", other);
                    std::process::exit(1);
                }
            };

            let sources = if !source_roots.is_empty() {
                // FF-9: Import-driven resolution from source roots
                let index = build_module_index(&source_roots);
                eprintln!("indexed {} modules from {} source roots", index.len(), source_roots.len());

                // Entry modules: all .dag files in the FIRST source root
                // (the compiler source). Transitive deps (std, extdeps) are
                // pulled in by import resolution.
                let first_root = std::path::Path::new(&source_roots[0]);
                let mut entry_files = Vec::new();
                if first_root.is_dir() {
                    // Recursively find all .dag files in the first source root
                    let mut dag_paths = Vec::new();
                    collect_dag_files(first_root, &mut dag_paths);
                    for path in dag_paths {
                        let content = std::fs::read_to_string(&path)
                            .unwrap_or_else(|e| panic!("failed to read {:?}: {}", path, e));
                        entry_files.push((path.to_string_lossy().to_string(), content));
                    }
                }

                // Seed the seen map with entry files to prevent duplicates
                let mut seen: HashMap<String, Rc<v2_compiler_compile::SourceFile>> = HashMap::new();
                let mut entry_for_queue = Vec::new();
                for (path, content) in &entry_files {
                    if let Some(mod_path) = extract_module_path(content) {
                        let source = Rc::new(v2_compiler_compile::SourceFile {
                            path: path.clone(),
                            content: content.clone(),
                        });
                        seen.insert(mod_path, source);
                    }
                    entry_for_queue.push((path.clone(), content.clone()));
                }

                // Resolve transitive imports (skips already-seen entry modules)
                let mut resolved = resolve_transitively_with_seen(entry_for_queue, &index, seen);
                // Add entry sources that weren't already in the resolved set
                for (path, content) in entry_files {
                    let already_there = resolved.iter().any(|s| s.path == path);
                    if !already_there {
                        resolved.push(Rc::new(v2_compiler_compile::SourceFile { path, content }));
                    }
                }
                eprintln!("resolved {} sources (transitive import closure)", resolved.len());
                resolved

            } else if let Some(dir) = source_dir {
                // Legacy: flat directory scan (backward compatibility)
                let mut dag_paths = Vec::new();
                collect_dag_files(std::path::Path::new(&dir), &mut dag_paths);
                let mut sources = Vec::new();
                for path in &dag_paths {
                    let content = std::fs::read_to_string(path)
                        .unwrap_or_else(|e| panic!("failed to read {:?}: {}", path, e));
                    let filename = path.file_name().unwrap().to_string_lossy().to_string();
                    sources.push(Rc::new(v2_compiler_compile::SourceFile {
                        path: filename,
                        content,
                    }));
                }
                eprintln!("compiling {} .dag files from {} (target: {})", sources.len(), dir, target);
                sources

            } else {
                eprintln!("error: provide --source-root or --source-dir");
                std::process::exit(1);
            };

            let result = v2_compiler_compile::compile_sources(sources, render_target);

            std::fs::create_dir_all(format!("{}/src", output_dir))
                .unwrap_or_else(|e| panic!("failed to create output dir: {}", e));
            for file in result.files.iter() {
                let out_path = format!("{}/{}", output_dir, file.path);
                if let Some(parent) = std::path::Path::new(&out_path).parent() {
                    std::fs::create_dir_all(parent).ok();
                }
                std::fs::write(&out_path, &*file.content)
                    .unwrap_or_else(|e| panic!("failed to write {}: {}", file.path, e));
            }
            eprintln!("compiled: {} files emitted, {} diagnostics",
                result.files.len(), result.diagnostics.len());
            render_diagnostics(&result);
            if result.files.is_empty() {
                eprintln!("error: no files emitted");
                std::process::exit(1);
            }
        },
    };
}

fn render_diagnostics(result: &PipelineResult) {
    if result.diagnostics.is_empty() {
        return;
    }

    // Build file → NewlineIndex lookup.
    let index_map: HashMap<String, Rc<NewlineIndex>> = result
        .newline_indices
        .iter()
        .map(|idx| (idx.file.clone(), idx.clone()))
        .collect();

    // Render all diagnostics. No cascade tree — when a stage produces
    // causal edges, re-add caused_by with both producer and consumer.
    for d in &result.diagnostics {
        render_one_diagnostic(d, &index_map, "");
    }

    eprintln!("\n{} error(s)", result.diagnostics.len());
}

fn render_one_diagnostic(
    d: &v2_compiler::v2_std_core::ErrorNode,
    index_map: &HashMap<String, Rc<NewlineIndex>>,
    indent: &str,
) {
    let severity = if is_error_diagnostic(d.diagnostic.clone()) { "error" } else { "warning" };
    let message = diagnostic_to_message(d.diagnostic.clone());
    let span = diagnostic_to_span(d.diagnostic.clone());

    // Resolve file:line:col if we have a newline index for this file.
    let location = if !span.file.is_empty() {
        if let Some(idx) = index_map.get(&span.file) {
            let lc = byte_to_line_col(idx.clone(), span.start);
            format!("{}:{}:{}", span.file, lc.line, lc.col)
        } else {
            span.file.clone()
        }
    } else if !d.module_name.is_empty() {
        d.module_name.clone()
    } else {
        String::new()
    };

    // Print error header.
    if location.is_empty() {
        eprintln!("{}{}: {}", indent, severity, message);
    } else {
        eprintln!("{}{}[{}]: {}", indent, severity, location, message);
    }

    // Print source context if we have a newline index.
    if !span.file.is_empty() {
        if let Some(idx) = index_map.get(&span.file) {
            let lc = byte_to_line_col(idx.clone(), span.start);
            let line_text = source_line_at(idx.clone(), lc.line);
            let line_num = format!("{}", lc.line);
            let gutter_width = line_num.len();
            eprintln!("{} {} |", indent, " ".repeat(gutter_width));
            eprintln!("{} {} | {}", indent, line_num, line_text);

            // Caret span.
            let span_len = std::cmp::max(1, (span.end - span.start) as usize);
            let col_offset = (lc.col - 1) as usize;
            eprintln!(
                "{} {} | {}{}",
                indent,
                " ".repeat(gutter_width),
                " ".repeat(col_offset),
                "^".repeat(std::cmp::min(span_len, line_text.len().saturating_sub(col_offset)))
            );
        }
    }
}
